function makeLine(x1, y1, x2, y2, name) {
  const line = figma.createLine();
  line.name = name;
  line.strokes = [{ type: "SOLID", color: rgb("#9CA3AF") }];
  line.strokeWeight = 1;
  line.x = x1;
  line.y = y1;
  line.resize(Math.max(1, x2 - x1), Math.max(1, y2 - y1));
  root.appendChild(line);
  createdNodeIds.push(line.id);
  return line;
}

